    """Extend a horizontal foreground bar to the right edge with color 1,
    when it begins at the left edge and leaves a short background tail."""
    if not grid:
        return []
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
