 "content": "def transform(grid):
    """Color the blank suffix after a single uninterrupted horizontal run."""
    if not grid:
        return []
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        foreground = [c for c, value in enumerate(row) if value != background]
        if not foreground:
            continue
        first, last = foreground[0], foreground[-1]
        # Only a single contiguous run ending before the right border qualifies.
        if last < len(row) - 1 and len(foreground) == last - first + 1:
            for c in range(last + 1, len(row)):
                out[r][c] = 1
    return out

